body[data-lang="en"] .hi { display: none !important; }
body[data-lang="hi"] .en { display: none !important; }

.lang-switcher {
    position: absolute;
    top: 60px;
    right: 5%;
    z-index: 1000;
    display: flex;
    gap: 5px;
    background: #fff;
    padding: 5px;
    border-radius: 30px;
    box-shadow: 0 4px 10px rgba(0,0,0,0.1);
    border: 2px solid var(--saffron-main);
}

.lang-btn {
    background: transparent;
    border: none;
    padding: 6px 15px;
    border-radius: 20px;
    font-family: 'Lato', sans-serif;
    font-weight: 700;
    color: var(--text-dark);
    cursor: pointer;
    transition: 0.3s;
}

.lang-btn.active {
    background: var(--saffron-dark);
    color: #fff;
}

/* Background Pattern */
.bg-pattern {
    position: fixed; top: 0; left: 0; width: 100%; height: 100%; 
    background-image: radial-gradient(var(--saffron-main) 0.5px, transparent 0.5px); 
    background-size: 30px 30px; opacity: 0.15; z-index: -1;
}

/* SCROLLING BANNER */
.news-ticker {
    height: 50px; width: 100%; overflow: hidden; position: relative; z-index: 100; 
    background: linear-gradient(135deg, var(--header-grad-start), var(--header-grad-end)); 
    border-bottom: 2px solid var(--saffron-dark); box-shadow: 0 4px 10px rgba(0,0,0,0.1);
}
.ticker-container {
    display: flex; height: 100%; animation: scroll-news 30s linear infinite;
}
@keyframes scroll-news {
    0% { transform: translateX(0); }
    100% { transform: translateX(-50%); }
}
.news-item {
    display: flex; align-items: center; padding: 0 40px; color: #fff; 
    font-family: 'Lato', sans-serif; font-weight: 700; white-space: nowrap; flex-shrink: 0; 
}
.news-btn {
    background: rgba(255,255,255,0.2); border: 1px solid rgba(255,255,255,0.8); 
    color: #fff; padding: 4px 15px; border-radius: 20px; text-decoration: none; font-size: 13px; margin-left: 15px;
}

/* HERO SECTION */
.profile-hero {
    display: flex; flex-wrap: wrap; align-items: center; justify-content: center; 
    padding: 80px 5% 60px; gap: 50px; max-width: 1400px; margin: 0 auto;
}
.hero-text-col { flex: 1; min-width: 350px; }
.peeth-tag {
    display: inline-block; color: var(--saffron-dark); font-weight: 700; 
    letter-spacing: 2px; text-transform: uppercase; font-size: 0.9rem; 
    margin-bottom: 15px; border-bottom: 2px solid var(--saffron-dark); 
    font-family: 'Lato', sans-serif;
}
.main-title {
    font-family: 'Cinzel', serif; font-size: clamp(2rem, 4vw, 3.5rem); 
    color: #3E1E08; line-height: 1.2; margin-bottom: 15px; 
}
.sub-title { font-size: 1.2rem; color: #8D6E63; margin-bottom: 30px; font-family: 'Lato', sans-serif; }

.info-grid { display: flex; gap: 20px; flex-wrap: wrap; margin-top: 30px; }
.info-item {
    flex: 1; min-width: 140px; background: #fff; border: 2px solid var(--saffron-main); 
    padding: 15px; border-radius: 10px; text-align: center; 
}
.info-label { font-size: 0.8rem; text-transform: uppercase; color: var(--saffron-dark); display: block; font-family: 'Lato', sans-serif; }
.info-val { font-weight: 700; font-size: 1.1rem; color: #3E1E08; font-family: 'Cinzel', serif; }

.hero-image-col { flex: 1; min-width: 300px; max-width: 450px; }
.portrait-frame {
    padding: 15px; background: #fff; border-radius: 15px; 
    box-shadow: 0 15px 40px rgba(211, 84, 0, 0.15); border: 2px solid var(--saffron-main);
}
.main-img { width: 100%; height: auto; display: block; border-radius: 10px; }
.img-caption {
    text-align: center; background: linear-gradient(to right, var(--saffron-dark), var(--saffron-main)); 
    color: #fff; padding: 10px; font-family: 'Cinzel', serif; margin-top: 10px; border-radius: 5px; font-size: 0.9rem;
}

/* RICH TEXT BOXES */
.content-container { max-width: 1000px; margin: 0 auto 50px; padding: 0 25px; }
.rich-title {
    border: 2px solid var(--saffron-dark); color: #fff; line-height: 1.2; 
    font-family: 'Alegreya', serif; font-size: 1.8em; margin-bottom: 25px; 
    background: linear-gradient(135deg, var(--header-grad-start), var(--header-grad-end)); 
    border-radius: 15px; box-shadow: 0 5px 20px var(--shadow-saffron); 
    padding: 20px; text-align: center; font-weight: 700;
}
.rich-box {
    border: 2px solid var(--saffron-main); color: var(--text-dark); 
    font-family: 'Alegreya', serif; font-size: 1.2rem; font-weight: 400; 
    background: linear-gradient(135deg, var(--box-grad-start), var(--box-grad-end)); 
    border-radius: 15px; padding: 35px; margin-bottom: 30px; text-align: justify;
}
.rich-heading {
    color: #D35400; font-weight: 700; font-size: 1.3em; display: block; 
    margin-bottom: 10px; border-bottom: 1px solid rgba(211, 84, 0, 0.2); padding-bottom: 5px;
}

@media (max-width: 768px) {
    .profile-hero { flex-direction: column-reverse; text-align: center; padding-top: 100px; }
    .hero-image-col { width: 100%; }
    .lang-switcher { top: 60px; right: 50%; transform: translateX(50%); }
}
